def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find a solid separator row or column whose color does not occur elsewhere.
    split = None
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            color = row[0]
            if sum(v == color for line in grid for v in line) == w:
                split = ("row", r)
                break
    if split is None:
        for c in range(w):
            color = grid[0][c]
            if all(row[c] == color for row in grid) and sum(row[c] == color for row in grid) == h and sum(v == color for row in grid for v in row) == h:
                split = ("col", c)
                break
    if split is None:
        raise ValueError("no unique solid separator found")
    axis, index = split
    if axis == "row":
        a, b = grid[:index], grid[index + 1:]
        shared = set(v for row in a for v in row) & set(v for row in b for v in row)
        base = max(shared, key=lambda color: sum(v == color for row in a + b for v in row))
        return [[3 if x == y else base for x, y in zip(ra, rb)] for ra, rb in zip(a, b)]
    a = [row[:index] for row in grid]
    b = [row[index + 1:] for row in grid]
    shared = set(v for row in a for v in row) & set(v for row in b for v in row)
    base = max(shared, key=lambda color: sum(v == color for row in a + b for v in row))
    return [[3 if x == y else base for x, y in zip(ra, rb)] for ra, rb in zip(a, b)]
